S['VT5MARGIN'] = [{'k': 'hook', 'ch': 'Mở đầu', 'label': 'Vì sao thật tệ khi…', 'cap': ('THỊ TRƯỜNG GIẢM 23%', 'TÀI KHOẢN MẤT 46%'), 'cols': ((255, 255, 255), (239, 68, 68)), 'anh': 'File:Sở GDCK TPHCM (HOSE).JPG', 'say': 'Thị trường giảm hai mươi ba phần trăm. Nhưng tài khoản của Tuấn mất bốn mươi sáu phần trăm. Và đó mới chỉ là ngày đầu tiên của cơn ác mộng.'}, {'k': 'bignum', 'cap': ('9 GIỜ TỐI', 'MỘT TIN NHẮN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'value': 35, 'fmt': '{:,.0f}', 'unit': '%', 'top': 'TỶ LỆ KÝ QUỸ CÒN', 'sub': 'yêu cầu nộp thêm tiền trước 10 giờ sáng mai', 'col': (239, 68, 68), 'say': 'Chín giờ tối thứ Năm, điện thoại Tuấn rung lên. Một tin nhắn từ công ty chứng khoán: tỷ lệ ký quỹ của quý khách đã xuống dưới mức duy trì. Đề nghị nộp thêm tiền trước mười giờ sáng mai. Nếu không, hệ thống sẽ tự bán.'}, {'k': 'text', 'cap': ('VÌ SAO THẬT TỆ KHI', 'VAY MARGIN ĐU ĐỈNH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'Ho Chi Minh City skyline', 'say': 'Tuấn không phải người liều. Anh là nhân viên văn phòng, hai mươi chín tuổi, có năm trăm triệu đồng dành dụm suốt sáu năm để cưới vợ. Vậy làm sao một người cẩn thận như vậy lại rơi vào tình huống này? Đây là câu chuyện vì sao thật tệ khi vay margin đu đỉnh. Nhân vật là hư cấu, nhưng từng con số trong video đều tính được, và rất nhiều người ngoài đời đã đi đúng con đường này.'}, {'k': 'text', 'ch': 'Chương 1 – Bữa tiệc mà ai cũng được mời', 'cap': ('AI CŨNG ĐANG LÃI', 'TRỪ MÌNH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'anh': 'coffee shop Vietnam', 'say': 'Mọi chuyện bắt đầu ở quán cà phê. Cậu bạn thân thời đại học khoe vừa lãi ba mươi phần trăm trong hai tháng. Chị kế toán trong công ty mua được xe mới. Nhóm chat chứng khoán mỗi tối đều có người đăng ảnh tài khoản xanh lè. Tuấn để năm trăm triệu trong sổ tiết kiệm, mỗi tháng nhận khoảng ba triệu tiền lãi. Ngồi giữa những câu chuyện đó, anh bắt đầu thấy mình là người chậm chân nhất bàn. Đây là cảm giác nguy hiểm nhất trong đầu tư.'}, {'k': 'text', 'cap': ('AI CŨNG ĐANG LÃI', 'TRỪ MÌNH'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'Ho Chi Minh City skyline', 'say': 'Không phải sợ mất tiền, mà là sợ bị bỏ lại.'}, {'k': 'cards', 'ch': 'Chương 2 – Nút bấm "mua tối đa"', 'cap': ('500 TRIỆU', 'THÀNH SỨC MUA 1 TỶ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'cards': [('500 triệu', 'tiền thật của Tuấn', ''), ('500 triệu', 'tiền vay công ty chứng khoán', ''), ('1.000 triệu', 'giá trị cổ phiếu đứng tên', '')], 'say': 'Tuấn mở tài khoản, chuyển năm trăm triệu vào. Rồi anh để ý một dòng chữ trên ứng dụng: sức mua một tỷ đồng. Công ty chứng khoán sẵn sàng cho anh vay thêm đúng bằng số tiền anh có. Đó chính là margin, hay giao dịch ký quỹ. Chỉ cần bấm nút mua tối đa, năm trăm triệu của Tuấn biến thành một tỷ đồng cổ phiếu. Nghe thì giống được tặng thêm một đôi chân. Nhưng thật ra, đó là một cái thang mượn.'}, {'k': 'cards', 'cap': ('500 TRIỆU', 'THÀNH SỨC MUA 1 TỶ'), 'cols': ((255, 255, 255), (255, 196, 0)), 'cards': [('500 triệu', 'tiền thật của Tuấn', ''), ('500 triệu', 'tiền vay công ty chứng khoán', ''), ('1.000 triệu', 'giá trị cổ phiếu đứng tên', '')], 'say': 'Người ta cho anh mượn thang để leo cao hơn, chứ không cho anh mượn dù để nhảy xuống.'}, {'k': 'bignum', 'ch': 'Chương 3 – Tuần trăng mật', 'cap': ('THỊ TRƯỜNG +10%', 'VỐN CỦA TUẤN'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 20, 'fmt': '+{:,.0f}', 'unit': '%', 'top': 'LÃI 100 TRIỆU', 'sub': 'trong vòng một tháng', 'col': (34, 197, 94), 'say': 'Tháng đầu tiên, mọi thứ đẹp như mơ. Cổ phiếu tăng mười phần trăm. Một tỷ thành một tỷ một trăm triệu. Nhưng tiền vay vẫn là năm trăm triệu, nên toàn bộ một trăm triệu tiền lãi thuộc về Tuấn. Vốn của anh tăng hai mươi phần trăm, gấp đôi thị trường. Tuấn bắt đầu nghĩ mình có năng khiếu. Anh tính nhẩm: cứ đà này, cuối năm có thể mua được nhà. Đòn bẩy làm lợi nhuận gấp đôi. Và cảm giác tự tin còn tăng nhanh hơn thế.'}, {'k': 'bignum', 'ch': 'Chương 4 – Khoản nợ không bao giờ ngủ', 'cap': ('LÃI VAY MARGIN', 'MỖI THÁNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'value': 5.4, 'fmt': '{:,.1f}', 'unit': ' triệu', 'top': 'VAY 500 TRIỆU · LÃI ~13%/NĂM', 'sub': 'chạy cả thứ Bảy, Chủ nhật, ngày lễ', 'col': (255, 196, 0), 'anh2': 'Saigon night', 'say': 'Có một thứ Tuấn không để ý. Khoản vay năm trăm triệu có lãi, khoảng mười ba phần trăm một năm, tùy công ty và tùy gói vay. Tính ra khoảng năm phẩy bốn triệu đồng mỗi tháng, gần bằng tiền thuê một căn hộ nhỏ ở thành phố. Và khoản lãi này không nghỉ cuối tuần, không nghỉ Tết. Thị trường đi ngang ba tháng, Tuấn vẫn mất khoảng mười sáu triệu. Nghĩa là cổ phiếu không chỉ cần tăng. Nó phải tăng đủ nhanh để thắng cả tiền lãi đang chạy mỗi ngày.'}, {'k': 'bignum', 'cap': ('LÃI VAY MARGIN', 'MỖI THÁNG'), 'cols': ((255, 255, 255), (255, 196, 0)), 'value': 5.4, 'fmt': '{:,.1f}', 'unit': ' triệu', 'top': 'VAY 500 TRIỆU · LÃI ~13%/NĂM', 'sub': 'chạy cả thứ Bảy, Chủ nhật, ngày lễ', 'col': (255, 196, 0), 'anh2': 'Saigon night', 'say': 'Sổ tiết kiệm trả tiền cho Tuấn khi anh ngủ. Còn margin thì lấy tiền của anh khi anh ngủ.'}, {'k': 'text', 'ch': 'Chương 5 – Mua thêm ở đỉnh', 'cap': ('CỔ PHIẾU ĐANG LÊN', 'SAO LẠI ĐỨNG NGOÀI?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'anh': 'File:Sở GDCK TPHCM (HOSE).JPG', 'say': 'Thị trường tiếp tục tăng thêm một chút. Nhóm chat bắt đầu nói về những mức điểm chưa từng có. Tuấn chốt lời một mã, rồi lại dùng toàn bộ sức mua mới để mua mã đang được nhắc nhiều nhất. Anh không đọc báo cáo tài chính của nó. Anh chỉ biết nó vừa tăng ba phiên liền và ai cũng đang nói về nó. Chính khoảnh khắc này mới là đu đỉnh. Không phải vì giá cao, mà vì lý do mua chỉ còn là: người khác đang mua.'}, {'k': 'bars', 'ch': 'Chương 6 – Khi thị trường quay đầu', 'cap': ('THỊ TRƯỜNG GIẢM', 'VỐN CỦA TUẤN MẤT'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'bars': [('Giảm 10%', 20, (255, 196, 0), '−20%'), ('Giảm 20%', 40, (239, 68, 68), '−40%'), ('Giảm 23%', 46, (239, 68, 68), '−46%'), ('Giảm 30%', 60, (239, 68, 68), '−60%')], 'say': 'Rồi thị trường quay đầu, chậm rãi lúc đầu. Giảm mười phần trăm, tài khoản Tuấn mất hai mươi phần trăm. Giảm hai mươi phần trăm, anh mất bốn mươi phần trăm số vốn. Đòn bẩy làm lợi nhuận gấp đôi lúc lên, thì cũng làm thua lỗ gấp đôi lúc xuống. Toán học không có thiên vị. Tuấn tự nhủ, chỉ là điều chỉnh. Anh không bán, vì bán bây giờ là chốt lỗ, mà chốt lỗ thì đau.'}, {'k': 'cards', 'ch': 'Chương 7 – Cuộc gọi lúc 9 giờ tối', 'cap': ('THỊ TRƯỜNG −23%', 'CHẠM VẠCH CALL MARGIN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'cards': [('770 triệu', 'giá trị cổ phiếu còn lại', ''), ('500 triệu', 'nợ vẫn y nguyên', ''), ('35%', 'tỷ lệ ký quỹ, chạm mức duy trì', '')], 'say': 'Đến khi thị trường giảm hai mươi ba phần trăm, một tỷ đồng cổ phiếu chỉ còn bảy trăm bảy mươi triệu. Nhưng khoản nợ thì vẫn y nguyên năm trăm triệu. Phần thật sự là của Tuấn chỉ còn hai trăm bảy mươi triệu, tức khoảng ba mươi lăm phần trăm tổng tài sản. Ở nhiều công ty chứng khoán, đây là quanh mức tỷ lệ duy trì. Đó là lúc tin nhắn chín giờ tối xuất hiện. Người ta gọi đó là call margin. Công ty chứng khoán không quan tâm cổ phiếu của Tuấn tốt hay xấu, sau này có lên lại hay không.'}, {'k': 'cards', 'cap': ('THỊ TRƯỜNG −23%', 'CHẠM VẠCH CALL MARGIN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'cards': [('770 triệu', 'giá trị cổ phiếu còn lại', ''), ('500 triệu', 'nợ vẫn y nguyên', ''), ('35%', 'tỷ lệ ký quỹ, chạm mức duy trì', '')], 'say': 'Họ chỉ quan tâm một điều: tiền cho vay phải được an toàn.'}, {'k': 'checklist', 'ch': 'Chương 8 – Ba lựa chọn, không cái nào dễ chịu', 'cap': ('ĐÊM ĐÓ TUẤN CÓ', '3 LỰA CHỌN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'items': [('Nộp thêm tiền: tiền ở đâu ra?', (255, 196, 0)), ('Tự bán bớt: chốt lỗ ngay', (255, 196, 0)), ('Không làm gì: bị bán giải chấp', (239, 68, 68))], 'say': 'Đêm đó, Tuấn có ba lựa chọn. Một, nộp thêm tiền. Nhưng toàn bộ tiền tiết kiệm đã nằm trong tài khoản rồi. Muốn nộp thêm, anh phải vay bố mẹ, vay người quen, hoặc quẹt thẻ tín dụng. Hai, tự bán bớt cổ phiếu để giảm nợ, tức là biến khoản lỗ trên giấy thành khoản lỗ thật. Ba, không làm gì cả, và sáng mai hệ thống sẽ tự bán thay anh, ở bất kỳ mức giá nào khớp được. Tuấn chọn cách mà rất nhiều người chọn.'}, {'k': 'checklist', 'cap': ('ĐÊM ĐÓ TUẤN CÓ', '3 LỰA CHỌN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'items': [('Nộp thêm tiền: tiền ở đâu ra?', (255, 196, 0)), ('Tự bán bớt: chốt lỗ ngay', (255, 196, 0)), ('Không làm gì: bị bán giải chấp', (239, 68, 68))], 'say': 'Anh gọi về nhà, nói dối là cần tiền đặt cọc thuê nhà, vay thêm một trăm triệu.'}, {'k': 'text', 'ch': 'Chương 9 – Vòng xoáy giải chấp', 'cap': ('TẤT CẢ CÙNG BỊ CALL', 'TẤT CẢ CÙNG PHẢI BÁN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'anh': 'storm clouds', 'say': 'Vấn đề là Tuấn không đứng một mình. Hàng nghìn tài khoản khác cũng vay margin, cũng nhận tin nhắn đó cùng một đêm. Sáng hôm sau, ai không nộp được tiền sẽ bị bán. Lệnh bán dồn dập đẩy giá giảm thêm. Giá giảm thêm lại làm thêm nhiều tài khoản chạm vạch. Giống như một hàng người đứng trên băng mỏng. Người đầu tiên ngã xuống làm cả mảng băng nứt theo.'}, {'k': 'text', 'cap': ('TẤT CẢ CÙNG BỊ CALL', 'TẤT CẢ CÙNG PHẢI BÁN'), 'cols': ((255, 255, 255), (239, 68, 68)), 'anh': 'Ho Chi Minh City skyline', 'say': 'Đó là lý do những cú giảm có margin thường nhanh và sâu hơn những gì báo cáo tài chính của doanh nghiệp có thể giải thích.'}, {'k': 'bars', 'ch': 'Chương 10 – Toán học không thương lượng', 'cap': ('ĐÃ MẤT', 'CẦN TĂNG BAO NHIÊU ĐỂ VỀ BỜ'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'bars': [('Mất 20%', 25, (255, 196, 0), '+25%'), ('Mất 46%', 85, (255, 196, 0), '+85%'), ('Mất 60%', 150, (239, 68, 68), '+150%'), ('Mất 80%', 400, (239, 68, 68), '+400%')], 'say': 'Một tuần sau, thị trường giảm ba mươi phần trăm. Vốn của Tuấn, tính cả một trăm triệu vay của gia đình, đã mất khoảng một nửa. Đây là phần toán học mà ít ai nói cho anh chị biết. Mất hai mươi phần trăm, cần tăng hai mươi lăm phần trăm để về bờ. Mất bốn mươi sáu phần trăm, cần tăng tám mươi lăm phần trăm. Mất sáu mươi phần trăm, cần tăng một trăm năm mươi phần trăm. Và mất tám mươi phần trăm, cần tăng tới bốn trăm phần trăm. Thua lỗ càng sâu, con đường về càng dài, theo cấp số không công bằng chút nào.'}, {'k': 'bignum', 'ch': 'Chương 11 – Chuyện này đã xảy ra thật', 'cap': ('VN-INDEX NĂM 2022', 'TỪ ĐỈNH XUỐNG ĐÁY'), 'cols': ((255, 255, 255), (239, 68, 68)), 'moc': True, 'value': -40.3, 'fmt': '{:,.1f}', 'unit': '%', 'top': '1.529 → 912 ĐIỂM', 'sub': 'đóng cửa 4/1/2022 → 16/11/2022', 'col': (239, 68, 68), 'say': 'Anh chị có thể nghĩ đây chỉ là chuyện tưởng tượng. Nhưng năm hai nghìn không trăm hai mươi hai, VN Index đóng cửa ở đỉnh khoảng một nghìn năm trăm hai mươi chín điểm vào ngày bốn tháng một. Đến giữa tháng mười một, chỉ số đóng cửa quanh chín trăm mười hai điểm, giảm khoảng bốn mươi phần trăm. Nhiều cổ phiếu đầu cơ còn giảm bảy mươi, tám mươi phần trăm. Với người không vay, đó là một năm buồn. Với người dùng margin tối đa ở vùng đỉnh, đó là năm tài khoản về gần bằng không.'}, {'k': 'text', 'ch': 'Chương 12 – Điều thật sự tệ', 'cap': ('MẤT TIỀN CHƯA PHẢI', 'ĐIỀU TỆ NHẤT'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'anh': 'Saigon night', 'say': 'Nhưng điều thật sự tệ khi vay margin đu đỉnh không chỉ là mất tiền. Đó là quỹ cưới sáu năm biến mất trong vài tháng. Là khoản nợ với gia đình mà anh phải nói dối để vay. Là những đêm không ngủ nhìn bảng giá nước ngoài. Và tệ nhất, là sau cú đó, nhiều người không bao giờ quay lại thị trường nữa. Họ bỏ lỡ luôn những năm thị trường hồi phục, chỉ vì một lần đi quá nhanh.'}, {'k': 'checklist', 'ch': 'Chương 13 – Nếu vẫn muốn dùng margin', 'cap': ('4 NGUYÊN TẮC', 'TRƯỚC KHI VAY'), 'cols': ((255, 255, 255), (255, 196, 0)), 'moc': True, 'items': [('Không dùng tiền sắp cần đến', (34, 197, 94)), ('Vay ít, không bao giờ mua tối đa', (34, 197, 94)), ('Tự đặt điểm dừng trước vạch call', (34, 197, 94)), ('Tính lãi vay vào kỳ vọng lợi nhuận', (255, 196, 0))], 'say': 'Margin không phải ác quỷ. Nó là một công cụ, như con dao trong bếp. Vấn đề là ai cầm và cầm lúc nào. Nếu anh chị vẫn muốn dùng, có bốn nguyên tắc. Một, không bao giờ dùng tiền sắp cần đến, như tiền cưới, tiền nhà, tiền học. Hai, vay ít, đừng bao giờ bấm mua tối đa. Ba, tự đặt điểm dừng lỗ của mình trước khi công ty chứng khoán đặt hộ. Bốn, cộng tiền lãi vay vào bài toán.'}, {'k': 'checklist', 'cap': ('4 NGUYÊN TẮC', 'TRƯỚC KHI VAY'), 'cols': ((255, 255, 255), (255, 196, 0)), 'items': [('Không dùng tiền sắp cần đến', (34, 197, 94)), ('Vay ít, không bao giờ mua tối đa', (34, 197, 94)), ('Tự đặt điểm dừng trước vạch call', (34, 197, 94)), ('Tính lãi vay vào kỳ vọng lợi nhuận', (255, 196, 0))], 'say': 'Nếu kỳ vọng lợi nhuận không thắng nổi mười ba phần trăm một năm, khoản vay đó không đáng.'}, {'k': 'text', 'cap': ('BIẾT MÌNH ĐANG MUA GÌ', 'TRƯỚC KHI VAY TIỀN MUA'), 'cols': ((255, 255, 255), (255, 196, 0)), 'anh': 'File:Sở GDCK TPHCM (HOSE).JPG', 'say': 'Và quan trọng hơn hết, đừng vay tiền để mua thứ mình không hiểu. Tuấn chưa từng mở báo cáo tài chính của mã mình mua. Nếu anh chị muốn xem nhanh P trên E, biên lợi nhuận và kết quả kinh doanh của hơn bốn trăm mã trước khi xuống tiền, em có tổng hợp sẵn trên chứng khoán Huy Nguyễn chấm com.'}, {'k': 'end', 'cap': ('ANH CHỊ ĐÃ TỪNG', 'BỊ CALL MARGIN CHƯA?'), 'cols': ((255, 255, 255), (255, 196, 0)), 'say': 'Câu chuyện của Tuấn là hư cấu. Nhưng nếu anh chị đã từng nhận tin nhắn chín giờ tối đó, anh chị sẽ biết nó thật đến mức nào. Anh chị đã từng bị call margin chưa, và bài học lớn nhất của anh chị là gì? Bình luận cho em biết nhé. Video tiếp theo: vì sao thật tệ khi vào nhóm phím hàng.'}]
